def editorial_home():
 return f'''<section id="home-hero" tabindex="-1" class="page-hero hero-home editorial-home"><img class="botanical hero-botanical" src="/assets/images/botanical-engraving.png" alt="" aria-hidden="true"><div class="container"><div class="editorial-title"><p class="eyebrow">INDIRECT PROCUREMENT, ON SOLID GROUND</p><h1>Every quote. A clear<br> decision record.</h1><p class="hero-intro">Compare low-risk RFQs and negotiate only inside approved boundaries.</p><div class="hero-actions">{link('Explore demo','/demo/','primary','flip')}{link('Discuss a pilot','/request-pilot/','secondary')}</div><p class="hero-caption">Research-stage concept · <a href="#intro" data-intro-replay>Watch the intro ↗</a></p><p class="hand-note hero-annotation">Same spend.<br>Better decisions.</p></div><div class="hero-register"><span>PEOPLE <br>PROCESS <br>RECORDS <br>BETTER OUTCOMES</span><span>14 OCTOBER 2026<br><i></i>VOL. I</span></div>{editorial_workbench()}<div class="hero-bottom"><span>Fictional buyer and suppliers · all external actions disabled</span><div><button class="motion-toggle" aria-pressed="false">Pause motion {ico('pause')}</button><button class="motion-replay">Replay {ico('rotate-ccw')}</button></div></div></div></section>'''
def editorial_evidence():
 return f'''<section class="section editorial-evidence"><div class="container evidence-layout"><div class="evidence-copy">{eyebrow('FROM QUOTE TO CONTEXT')}<h2>The number is only<br>the beginning.</h2><p>A lower price can still fall outside policy, miss key requirements, or create risk. SourcingRecord captures the details, normalizes what matters, and helps your team make the right call — with a clear record.</p></div><div class="evidence-art" data-motion><article class="source-paper"><div><b>Forgefield Services</b><b>Q-202-J v1</b></div><p>Date: 12 Oct 2026<br>Terms: Net 30<br>Freight: Included</p><a class="source-highlight" href="/demo/workbench/?view=source"><span>200 pairs safety gloves</span><b>$1,020</b></a><p>Lead time: 30 days<br>Specification: SG-A v1<br>Notes: No substitutions without<br>prior approval.</p><small>DEMO — SYNTHETIC DATA</small></article><p class="hand-note quote-annotation">Lower price,<br>longer lead time.<br>Within policy,<br>but confirm<br>operational need.</p></div></div></section>'''
def editorial_modules():
 descriptions=['Normalize requisitions, pack sizes and specifications with source evidence.','Collect competitive RFQs and compare like-for-like quotes, landed costs and exceptions.','Monitor renewal clauses, changed wording and notice dates for human review.','Draft supplier negotiations on approved non-price terms, within explicit limits.','Verify negotiated outcomes against a draft PO and savings against an approved baseline.']
 names=['Requisition & specification normalization','Competitive RFQs & quote comparison','Renewal clauses & change notices','Constrained non-price negotiation','Outcome-to-PO & savings verification']
 rows=''.join(f'<a href="/products/{m["slug"]}/" data-offer="{m["id"]}"><span>0{m["id"]}</span><div><h3>{names[m["id"]-1]}</h3><small class="sr-only">{m["name"]} · Proposed module</small></div><p>{descriptions[m["id"]-1]}</p>{ico("arrow-right")}</a>' for m in mods)
 return f'''<section class="editorial-module-section"><div class="container editorial-module-layout"><div>{eyebrow('PROPOSED MODULES')}<div class="editorial-module-list">{rows}</div></div><aside><p class="eyebrow">A MORE<br>COMPLETE PICTURE</p><p>Same inputs.<br>More clarity.<br>A record you<br>can stand behind.</p><img class="botanical" src="/assets/images/botanical-engraving.png" alt="" aria-hidden="true"></aside></div></section>'''
def homepage_qualifier():
 return '<section class="section surface-paper homepage-qualifier"><div class="container qualifier-grid"><div>'+eyebrow('FOR THE INDIRECT PROCUREMENT HEAD')+'<p class="qualifier-copy">Midmarket teams. Repeat tail-spend RFQs and renewals. Too few category managers to review every detail.</p></div><div><p class="eyebrow">A WORKFLOW QUESTION, NOT A PERFORMANCE CLAIM</p><h2>How many RFQs did you review last month?</h2><p>And how many needed a manual check of pack sizes, freight or lead times? Start with anonymized closed RFQs and test whether the comparison surfaces missed alternatives.</p>'+textlink('Prepare a closed-RFQ diagnostic','/resources/sample-preparation/')+'</div></div></section>'
def homepage_review():
 return section('A draft you can challenge.<br>A decision you still own.','Inspect the evidence, see the proposed change and keep the supplier’s choice visible. Everything below is a deterministic, fictional example.',f'''<div class="review-pair"><article class="redline-folio"><p class="eyebrow">DEMO — SYNTHETIC DATA / NONBINDING DRAFT</p><div class="folio-heading"><h3>Delivery is the only proposed change.</h3><span class="sample-status hold">Held · pending review</span></div><p class="folio-source"><a href="/demo/workbench/?view=source">REQ-202 v1 → Q-202-J v1</a> · 12 Oct 2026<br>RF-202 · Forgefield Services · Juniper Goods</p><p class="redline-sentence">Deliver 200 pairs of SG-A v1 safety gloves within <del>15 calendar days</del> <ins>30 calendar days</ins>.</p><dl class="draft-policy"><div><dt>Floor / ceiling</dt><dd>15–30 days delivery</dd></div><div><dt>Fixed terms</dt><dd>$1,020 landed total · SG-A v1 · Net 30</dd></div><div><dt>Prohibited concessions</dt><dd>No price change, specification relaxation, payment-term change or liability concession.</dd></div></dl><p class="baseline-hold">30-day delivery differs from the prior 15-day purchase. Comparability stays held until the owner resolves operational need.</p><div class="approval-checkpoint">{ico('lock-keyhole')}<div><b>Lina Shaw · assigned reviewer</b><p>Human approval and signature required before binding terms. Sending and PO execution are disabled.</p></div></div><div class="inline-links">{textlink('Review or override the draft','/demo/workbench/?view=draft')}{textlink('Inspect the baseline','/resources/baseline-method/')}</div><small>DEMO · Suggested change, not an approved or completed order.</small></article><article class="supplier-folio"><p class="eyebrow">DEMO — SYNTHETIC DATA / SUPPLIER VIEW</p><h3>Participation stays a choice.</h3><ol class="consent-transcript"><li><span>12 OCT · 09:00 UTC / INVITATION</span><p>A supervised delivery discussion only. The quoted price, specification and payment terms remain fixed. Participation is voluntary.</p></li><li><span>09:05 UTC / JUNIPER GOODS</span><blockquote>“I agree to discuss delivery timing for this example. Our quoted total remains $1,020. Participation may be withdrawn.”</blockquote><a href="/demo/workbench/?view=supplier">CONSENT-202-J v1 · transcript entry 2</a></li><li><span>STONECAP / DECLINED</span><p>Opted out. Further draft progression is blocked; withdrawal cannot be overridden by the reviewer.</p></li></ol><div class="consent-actions">{link('Inspect supplier transcript','/demo/workbench/?view=supplier','secondary')}{textlink('Try the opt-out branch','/demo/workbench/?supplier=stonecap')}</div><small>DEMO · Invented organizations and dialogue. No message is sent.</small></article></div>''','white','THE EVIDENCE / THE APPROVAL','homepage-review')
def homepage_controls():
 return '<div class="homepage-control-notes"><article>'+ico('shield')+'<div><h3>Permissioned inputs. Purpose-limited review.</h3><p>Use anonymized closed RFQs only with permission. Review source access and source-to-pay mapping within the pilot. This preview collects no raw RFQs and makes no ERP, payment or supplier writes.</p><p>Inquiry forms prepare a local summary. No transmission or persistent storage; clear the form or reload to delete its contents. Privacy and optional email-interest choices are available in the preview.</p>'+textlink('Read the privacy preview','/legal/privacy/')+'</div></article><article>'+ico('circle-alert')+'<div><h3>The evidence decides whether to proceed.</h3><p>Require a repeatable category, named owner, authorized envelope, supplier consent and positive buyer-verified net value after review effort and relevant fees. Measure category-manager hours, omissions, supplier opt-outs and complaints; exclude unaccepted offers.</p><p><b>Stop on supplier relationship damage or baseline ambiguity.</b> Expand across categories or supplier management only if verified net savings and supplier experience survive control testing.</p>'+textlink('See acceptance and stop criteria','/pilot/#gates')+'</div></article></div>'

