 if id=='home':return editorial_home()
 p=hero_by[id]; dark=p['background']=='pine';caption={'request-pilot':'Inquiry preview · nothing submitted','contact':'Inquiry preview · nothing sent','privacy':'Privacy specification · preview only','terms':'Preview terms · draft for review','not-found':'Return to the record index'}.get(id,p['disclosure']);vis=visual or figure(id,caption)
 note={"bids-desk":"Keep the original.<br>Clarify the basis.","bids-review":"The total needs<br>its context.","bids-proof":"One clause.<br>Two versions.","bids-signal":"A conversation<br>with boundaries.","bids-report":"Count the costs.<br>Check the basis.","products":"Five jobs.<br>One clear record.","how-it-works":"A source for<br>every step.","pilot":"Start small.<br>Review the evidence."}.get(id,"A clearer record.<br>A considered decision.")
