for m in mods:
 body=hero(m['slug'],m['intro'],primary=('Inspect the demo example','/demo/workbench/?module='+str(m['id'])+'&view='+{1:'source',2:'compare',3:'compare',4:'draft',5:'report'}[m['id']]),secondary=('Discuss this module','/request-pilot/?offer='+str(m['id'])))
