bodies['how-it-works']=hero('how-it-works','Follow a supervised RFQ-to-PO comparison. Each proposed step has a source, an exception and a human owner.',primary=('Follow RF-202','/demo/workbench/'))+section('Prepare. Compare. Review.','The initial test stays narrow and permissioned.',workflow([('Prepare the basis','Normalize the specification and quantity from anonymized closed RFQs. Resolve missing units before comparison.'),('Compare and constrain','Show supplier alternatives and lead-time differences, then establish the owner’s non-price negotiation envelope.'),('Review and hand off','Inspect voluntary supplier participation, review the nonbinding draft and prepare a labeled draft handoff. Human signature precedes any binding terms.')]),'white','THE REVIEW LOOP')+chapter('Where the comparison<br>needs a correction.','Juniper’s 30-day delivery differs from the prior 15-day baseline. The owner can choose Delta or document a defensible adjustment. A cosmetic override cannot resolve consent or prohibited terms.',figure('workbench','DEMO — source, reviewer and opted-out branch.'),'mist',True,'EXCEPTIONS & OVERRIDE')+section('The pilot ends with evidence.','Measure buyer-reviewed net value, manager hours, omissions and false positives, supplier opt-outs and complaints. The paid pilot decision is a separate real-world commitment.',readiness(),'sage','VALIDATION')+cta()
bodies['use-cases']=hero('use-cases','For repeat tail-spend purchasing where the specification can be normalized and the supplier is willing to participate. The illustrative map is not a coverage claim.',primary=('Check category fit','/request-pilot/'))+section('A category has to earn its scope.','Repeatability, comparable source records and low-risk non-price terms are starting conditions, not proven demand.',workflow([('Repeat purchases','A known specification and repeated sourcing job make comparison review practical.'),('Comparable alternatives','More than one usable quote is available, with units and landed costs documented.'),('Willing suppliers','A supervised discussion depends on voluntary participation and a bounded envelope.')]),'white','CATEGORY FIT')+chapter('Safety gloves.<br>One concrete example.','The fictional RF-202 compares 200 pairs across three suppliers. The lower total has a delivery exception, and one supplier opted out.',quote_preview(),'paper',True,'THE SYNTHETIC CATEGORY')+section('Who might sponsor the test?','Acquisition paths to investigate, not current partnerships.',[''][0]+ '<div class="persona-rows">'+''.join(f'<article>{ico(icon)}<div><h3>{t}</h3><p>{b}</p></div></article>' for icon,t,b in [('building2','Midmarket procurement','An indirect procurement head with recurring low-value RFQs and limited category-manager capacity.'),('users-round','Portfolio shared services','A named owner coordinating repeat purchasing across related companies.'),('handshake','Consultancies and P2P partners','Partners who can recruit one category manager for a closed-RFQ diagnostic.')])+'</div>','mist','BUYER / CHANNEL HYPOTHESES')+cta()
bodies['controls']=hero('controls','Define the permitted term, the approved range and the human owner. In the concept demo, supplier contact, binding acceptance, payments and ERP writes are disabled.',primary=('Inspect demo limits','/demo/workbench/'))+section('The policy envelope is visible.','RF-202 fixes price, quantity, specification, payment and liability terms. Only delivery timing may be proposed inside the 15–30-day range.', '<div class="policy-ledger"><div><span>Permitted</span><b>Delivery · 15–30 days</b></div><div><span>Fixed</span><b>$1,020 · 200 pairs · SG-A v1</b></div><div><span>Prohibited</span><b>Specification, payment or liability concessions</b></div><div><span>Authority</span><b>Human approval before binding terms</b></div></div>','white','THE ENVELOPE')+chapter('Consent is a guard.<br>It is not a checkbox to bypass.','Supplier withdrawal invalidates pending approval and stops the draft path. The reviewer can inspect or correct an extraction, but cannot reinstate an opted-out supplier through an override.',figure('supplier-experience','DEMO — voluntary participation and blocked opt-out.'),'clay',True,'SUPPLIER AUTHORITY')+section('A source for every proposed field.','The record retains source IDs and versions, fixed dates, assumptions, owner and a dated next action. Changes reset the approval reference.',workflow([('Provenance','Keep source page, line, date and version beside the normalized field.'),('Correction','Record a reviewer reason and before/after value when a permitted assumption changes.'),('Handoff','Carry the approval and source references into a draft export with an illustrative watermark.')]),'mist','REVIEWABILITY')+section('Concept controls.<br>No certification claims.','Data-handling responsibilities, system mappings, access roles and legal terms would be assessed before live collection or a supervised pilot. No operating integration or audit certification is implied.', '<ul class="control-list">'+''.join(f'<li>{ico("ban")}<span>{x}</span></li>' for x in ['No autonomous supplier contact in initial scope.','No real sending, binding acceptance or financial actions in the demo.','No public raw-RFQ upload or sensitive record collection.','No production source-to-pay integration is presented as live.'])+'</ul>','paper','SYSTEM LIMITS')+cta()
bodies['supplier-experience']=hero('supplier-experience','The supplier sees the scope, the optional nature of the discussion and a clear route to decline or withdraw. Supplier experience is a pilot gate.',primary=('Open supplier-side demo','/demo/workbench/?view=supplier'),secondary=('Read participation guide','/resources/supplier-participation/'))+chapter('An invitation with<br>its limits attached.','A supervised delivery discussion does not give permission for unrelated concessions or future messages. The named human owner stays visible.',figure('supplier-participation','Illustrative participation sequence; consent is not created by an animation.'),'white',False,'SCOPE / OWNER / CHOICE')+section('A transcript you can inspect.','Every line below is fictional and stays inside the demo.', '<div class="transcript-public"><article><time>12 OCT 2026 / 09:00 UTC</time><h3>Demo invitation</h3><p>Forgefield is reviewing RF-202. This optional demonstration covers delivery timing only. Any draft needs human approval. You may decline or stop participating.</p></article><article><time>12 OCT 2026 / 09:05 UTC</time><h3>Fictional Juniper response</h3><p>I agree to discuss delivery timing for this example. Our quoted total remains $1,020.</p></article><article><time>14 OCT 2026 / 10:03 UTC</time><h3>Nonbinding draft</h3><p>Proposed delivery is 30 days after order instead of 15, within the approved range. All other terms remain unchanged. This draft has not been sent or accepted.</p></article></div>','paper','DEMO — SYNTHETIC DATA')+section('Decline has equal standing.','The supplier can stop participation. In the demo, withdrawal blocks further negotiation and invalidates approval.',faqs([('Does declining affect supplier standing in the concept?','The demo records a participation decision, not a performance or supplier-quality score. Opted-out suppliers cannot be contacted through the preview.'),('How would complaints be handled in a pilot?','A named sourcing owner must define an agreed human support and escalation route before a live test. Relationship harm is a reason to halt activity and review.'),('Can the supplier contact a human here?','Use the labeled contact preview to prepare an inquiry. No operational support inbox or response-time promise is fabricated.')]),'clay','SUPPLIER FAQ')+cta()
bodies['pilot']=hero('pilot','A category pilot is a test of a bounded purchase decision. Start with anonymized closed RFQs, then consider a supervised supplier-consented live test.',primary=('Prepare pilot inquiry','/request-pilot/'),secondary=('Inspect the demo','/demo/'))+section('Four entry gates.','Agree these before any supervised live RFQ.',f'<div id="gates">{readiness()}</div>','white','THE COMMITMENT')+section('Quote a bounded pilot.<br>Test whether a buyer commits.','The prices below are hypotheses. No demand, price acceptance or commercial performance has been demonstrated.',priceblock(),'cream','HYPOTHETICAL TEST PRICING')+section('Go on reviewed ground truth.','Demo polish, clicks and self-reported AI accuracy do not make a pilot successful.', '<div class="decision-table"><article><span class="status-label in-scope">Proceed</span><h3>Reviewable positive value</h3><p>Repeatable category, authorized envelope, supplier consent and positive net value after review effort and relevant fees.</p></article><article><span class="status-label held">Hold</span><h3>Ambiguous comparison</h3><p>Missing permission, incomplete specification, unapproved baseline or unclear authority.</p></article><article><span class="status-label blocked">Halt</span><h3>Relationship or authority harm</h3><p>Supplier complaints, unauthorized contact, consent bypass, prohibited concessions or manipulated baselines.</p></article></div>','sage','ACCEPTANCE / KILL CRITERIA')+cta('Name the category.<br>Name the owner.','Use the inquiry preview to prepare the scope you would want to discuss.')
bodies['request-pilot']=hero('request-pilot','Prepare a category-pilot inquiry. This preview keeps your details in the current page and does not send, store or claim receipt of a request.',primary=('Prepare the inquiry','/request-pilot/#inquiry'),secondary=('Review test pricing','/pilot/'))+section('A useful starting brief.','No raw records or payment required.',f'<div id="inquiry">{form("pilot")}</div>','white','PILOT INQUIRY PREVIEW')
bodies['resources']=hero('resources','Practical reading for a source-linked comparison, a voluntary supplier conversation and a permissioned pilot sample.',primary=('Browse the guides','/resources/#guides'))+section('Three guides.<br>One reviewable method.','These concept-stage methods support a buyer conversation. They are informational and do not replace company policy or counsel review.',f'<div id="guides">{resources_cards()}</div>','white','THE READING ROOM')+cta()
bodies['baseline-method']=hero('baseline-method','Start with a prior comparable purchase. Document the adjustments and incremental costs before counting any accepted outcome as value.',primary=('Open the illustrative report','/demo/workbench/?view=report'))+section('Match the basis first.','The baseline is held until the owner can approve a defensible comparison.',workflow([('Quantity and specification','Compare the same required specification and normalized quantity; keep source versions.'),('Freight, currency and terms','Document landed cost, freight, relevant taxes, currency basis and delivery conditions.'),('Incremental costs','Account for review hours, approved hourly cost, pilot fee allocation and other category-specific costs.')]),'white','THE CHECKLIST')+chapter('The RF-202 calculation<br>is deliberately held.','The prior purchase is $1,140 at 15 days. Juniper is $1,020 at 30 days. A lower number cannot silently resolve that delivery difference.',figure('bids-report','Illustrative cost chart; not realized savings.'),'sage',True,'THE FAILED RECOMMENDATION')+section('What the arithmetic actually says.','If comparability were explicitly approved with a zero delivery adjustment, the synthetic arithmetic would be:', '<div class="calculation-ledger"><div><span>Prior basis − quote total</span><b>$1,140 − $1,020 = $120</b></div><div><span>Review cost</span><b>0.5h × $60/h = $30</b></div><div><span>Scenario before fees</span><b>$120 − $30 = $90</b></div><div class="negative"><span>Whole $2,500 pilot fee on one order</span><b>$90 − $2,500 = −$2,410</b></div></div><p class="small-note">This single-order scenario does not establish positive pilot value. Purchase frequency, allocation and reviewed net value need buyer evidence. Unaccepted offers remain excluded from savings.</p>','paper','ILLUSTRATIVE / SYNTHETIC INPUTS')+cta()
bodies['supplier-participation']=hero('supplier-participation','Define the purpose, the permitted term and the named owner. Participation remains optional throughout the discussion.',primary=('Inspect the supplier view','/demo/workbench/?view=supplier'))+section('Specific consent.<br>A clear withdrawal route.','A supplier invitation should state the scope, the draft status, who can bind terms and how to stop participation.',workflow([('Explain the scope','Identify the RFQ, the authorized non-price term and the sourcing owner.'),('Record the choice','Keep a dated participation response linked to the scope version.'),('Respect withdrawal','Stop draft progression and invalidate pending approval when consent is withdrawn.')]),'white','PARTICIPATION METHOD')+chapter('The decline branch<br>must work.', 'Stonecap has opted out in the fictional RF-202 example. The owner can inspect its quote source, but cannot advance a negotiation or reactivate participation through a generic override.',figure('supplier-experience','DEMO — opted-out supplier branch blocked.'),'clay',True,'THE SUPPLIER EXAMPLE')+cta()
bodies['sample-preparation']=hero('sample-preparation','A closed-RFQ diagnostic needs permissioned, anonymized examples. This public preview accepts no uploads or sensitive raw supplier records.',primary=('Prepare a diagnostic inquiry','/request-pilot/'))+section('Permission before transfer.','Agree an actual approved data route with the named sourcing owner before any real diagnostic.',workflow([('Confirm permission','Establish the right to use the sample and minimize the source information required.'),('Use neutral identifiers','Remove real company, supplier and personal identifiers from the diagnostic example.'),('Retain the comparison fields','Specification, pack size, quantity, freight, currency, delivery, source date and reviewer assumptions.')]),'white','SAMPLE CHECKLIST')+section('Keep raw records out<br>of public forms and analytics.','The website captures no sensitive RFQ data. Future Notion tracking should use structured summaries and controlled references, never raw records.', '<ul class="control-list">'+''.join(f'<li>{ico("file-check2")}<span>{x}</span></li>' for x in ['Segment, buyer role and present workflow.','Permissioned sample count and selected offer.','Owner, budget, data-access and reviewer readiness.','Reviewed baseline versus outcome, omissions and next step.'])+'</ul>','mist','PURPOSE / MINIMIZATION')+cta()
bodies['about']=hero('about','Our proposed mission is to make supervised sourcing an evidence-linked decision process. The human owner retains authority, and the record keeps the basis of the decision in view.',primary=('Read the workflow','/how-it-works/'),secondary=('Contact preview','/contact/'))+chapter('Start narrow.<br>Earn the next category.','The initial scope is one repeatable tail-spend category, anonymized closed RFQs and a supervised supplier-consented live test. No autonomous supplier contact is part of that starting scope.',figure('illustration-reviewer','Illustrative reviewer role; not a real employee.'),'white',True,'OUR APPROACH')+section('What must be proven.','Category-specific normalization and constrained drafts may earn budget only if reviewed net value and supplier experience improve. Incumbent overlap makes differentiation uncertain.',workflow([('A useful comparison','Buyer-adjudicated alternatives and exceptions, with omissions and false positives recorded.'),('A willing participant','Supplier consent and experience that survive the supervised test.'),('A real purchase decision','A paid pilot commitment followed by reviewed positive net value, not a demo completion.')]),'mist','THE RESEARCH QUESTIONS')+section('Research-stage, clearly stated.','This website presents a concept and synthetic product preview. It does not establish customer demand, million-dollar revenue, real customers, production integrations or pricing acceptance.',resources_cards(),'paper','THE COMPANY RECORD')+cta()
