bodies['sign-in']=hero('sign-in','A composed access page for a proposed pilot workspace. Authentication is not connected; use the synthetic demo to inspect the workflow without an account.',primary=('Open demo workspace','/demo/workbench/'))+section('Access by a bounded pilot.','No credentials are collected by this concept website.', '<div class="auth-layout"><aside><h2>One category.<br>A named owner.</h2><p>A future pilot workspace would follow permissioned data access, agreed roles and approved scope.</p>'+textlink('Review the pilot gates','/pilot/')+'</aside><div class="auth-card"><h3>Pilot workspace</h3><p>Authentication preview · not connected</p><label for="access-email">Work email</label><input id="access-email" type="email" placeholder="you@company.com" disabled><label for="access-password">Password</label><input id="access-password" type="password" placeholder="Authentication is not connected" disabled><div class="auth-links"><span>Remember-me unavailable</span><a href="/contact/">Access help</a></div>'+link('Explore without signing in','/demo/workbench/')+'<small>No password is read or stored. <a href="/legal/privacy/">Privacy preview</a></small></div></div>','white','PILOT ACCESS')
legal_privacy=[('Purpose and current scope','SourcingRecord is a research-stage website and synthetic demo. Pilot and contact forms are explicitly unconnected previews. No form contents are submitted to a server or saved to a lead system.'),('Local preview behavior','Form values remain in the current page memory until reload or clearing. A download is created only when you choose Download summary. The demo uses fictional records and changes only that local scenario.'),('Measurement in this preview','The site maintains a short, in-memory event inspection list containing allowlisted route, offer, source and scenario identifiers. It sends no analytics requests, stores no raw form values, and creates no marketing profile. Campaign strings are sanitized.'),('No raw records or payment','Do not enter supplier-sensitive or transaction-level information. There is no RFQ upload, payment collection, bank connection, ERP write or real supplier contact.'),('Operator details before real collection','The legal controller, recipient inbox, processors, actual retention and deletion contact must be confirmed before any real form intake is enabled. This page is a draft specification, not a completed operational privacy policy.'),('Clear or remove local information','Use Clear form or reload the page to remove form content from page memory. Any summary file you download is on your device and can be deleted there. For questions, use the contact preview; it does not send a message.')]
legal_terms=[('A concept preview','The site illustrates proposed modules and a supervised procurement workflow. It does not establish an operating SaaS, accepted prices, customers, certifications or live integrations.'),('Synthetic records','Forgefield Services, the suppliers, owners, quotes and outcomes in the demo are fictional. The demo is not procurement advice or an executed sourcing event.'),('Nonbinding drafts and disabled actions','A simulated approval is a demonstration state. Draft exports are labeled DEMO and are not purchase orders. Sending, binding acceptance, ERP writes, funds transfers and payment are disabled.'),('Hypothetical pricing','The $2,500 category pilot and $1,000–$3,500 monthly category range are test hypotheses. There is no active checkout or commercial acceptance represented here.'),('Human authority and supplier choice','Real pilot scope would require a named owner, authorized envelope, supplier consent and source review. No demo action establishes real authority or bypasses policy, contract or consent.'),('Legal review before operational launch','These preview terms are an informational draft. Company details, actual service terms, data handling and legal position require review before real intake or an operating service.')]
